// Rust guideline compliant 2026-02-21

use gpui_mesh::{DataSet,Field};
use gpui_scene3d::{Actor,Camera,Scene,TransferFunction,render};
use gpui_profiler::AllocProbe;
use std::{hint::black_box,time::Instant};

fn cpu_ns() -> u128 {
    let mut stamp=libc::timespec {tv_sec:0,tv_nsec:0};
    // SAFETY: stamp is valid writable storage for this synchronous clock call,
    // which retains no pointer. The return status and timestamp are checked.
    let result=unsafe {libc::clock_gettime(libc::CLOCK_PROCESS_CPUTIME_ID,&mut stamp)};
    assert_eq!(result,0);
    assert!(stamp.tv_sec>=0 && (0..1_000_000_000).contains(&stamp.tv_nsec));
    stamp.tv_sec as u128*1_000_000_000+stamp.tv_nsec as u128
}

fn image_hash(bytes:&[u8]) -> u64 {bytes.iter().fold(0xcbf29ce484222325,|hash,&v|(hash^u64::from(v)).wrapping_mul(0x100000001b3))}

fn actor(n:usize,case:&str,wire:bool,opacity:f32) -> Actor {
    let data=DataSet::structured_grid("cells",[n;3],[-1.0;3],[2.0/(n-1) as f64;3]).unwrap();
    let field=match case {
        "point" => Field::scalar("p",data.positions.iter().map(|p|(p[0]+1.0)*0.5).collect::<Vec<_>>()),
        "cell_uniform" => Field::scalar("p",vec![0.5;data.cell_count()]).on_cells(),
        "cell_varying" => Field::scalar("p",(0..data.cell_count()).map(|i|(i%(n-1)) as f64/(n-2) as f64).collect::<Vec<_>>()).on_cells(),
        "cell_missing" => {let mut f=Field::scalar("p",vec![0.5;data.cell_count()]).on_cells();f.valid=Some((0..data.cell_count()).map(|i|i%(n-1)!=(n-1)/2).collect::<Vec<_>>().into());f},
        _=>panic!("case")
    };
    let a=Actor::new(data.with_field(field));
    let a=if case=="point" {a.coloured_by("p",TransferFunction::viridis([0.0,1.0]))}else{a.coloured_by_cell("p",TransferFunction::viridis([0.0,1.0]))};
    a.wireframe(wire).opacity(opacity)
}

fn measure<T>(n:usize,size:u32,case:&str,wire:bool,opacity:f32,kind:&str,payload:u64,hash:u64,mut run:impl FnMut()->T,mut check:impl FnMut(T)) {
    check(run());
    let (mut times,mut cpus,mut calls,mut bytes)=(Vec::new(),Vec::new(),Vec::new(),Vec::new());
    for _ in 0..5 {
        let mut probe=AllocProbe::new(); let before=cpu_ns(); let start=Instant::now();
        let out=black_box(run()); let elapsed=start.elapsed().as_nanos(); let cpu=cpu_ns()-before;
        let allocation=probe.sample("wireframe");
        times.push(elapsed);cpus.push(cpu);calls.push(allocation.count);bytes.push(allocation.bytes);
        check(out);
    }
    println!(r#"{{"n":{n},"size":{size},"case":"{case}","wire":{wire},"opacity":{opacity},"kind":"{kind}","payload_bytes":{payload},"image_hash":"{hash:016x}","times_ns":{times:?},"cpu_times_ns":{cpus:?},"allocation_calls":{calls:?},"allocated_bytes":{bytes:?},"allocator_instrumentation":{}}}"#,cfg!(feature="allocations"));
}

fn software(n:usize,size:u32,case:&str,wire:bool,opacity:f32) {
    let scene=Scene::new().with_actor(actor(n,case,wire,opacity));
    let camera=Camera::fitted(scene.bounds().unwrap());
    let expected=render(&scene,&camera,size,size).unwrap();
    let background=scene.background.map(|v|(v.clamp(0.0,1.0)*255.0) as u8);
    assert!(expected.rgba.chunks_exact(4).any(|p|p!=background));
    let payload=scene.prepare().unwrap().byte_len();
    measure(n,size,case,wire,opacity,"software",payload,image_hash(&expected.rgba),||render(&scene,&camera,size,size).unwrap(),|out|assert_eq!(out.rgba,expected.rgba));
    assert_eq!(scene.preparation_stats().geometry_builds,1);
}

fn prepare(n:usize,case:&str,wire:bool) {
    let actor=actor(n,case,wire,1.0);
    let sample=Scene::new().with_actor(actor.clone()); let payload=sample.prepare().unwrap().byte_len(); drop(sample);
    measure(n,0,case,wire,1.0,"prepare",payload,0,|| {
        let scene=Scene::new().with_actor(actor.clone()); let prepared=scene.prepare().unwrap(); (scene,prepared)
    },|(scene,prepared)| {
        assert_eq!(prepared.byte_len(),payload); assert!(prepared.matches(&scene).unwrap()); assert_eq!(scene.preparation_stats().geometry_builds,1);
    });
}

#[cfg(feature="gpu")]
fn gpu(renderer:&gpui_scene3d::GpuRenderer,n:usize,case:&str,wire:bool,opacity:f32) {
    let scene=Scene::new().with_actor(actor(n,case,wire,opacity));
    let camera=Camera::fitted(scene.bounds().unwrap());
    let mut uploaded=renderer.upload(&scene).unwrap();
    let target=renderer.create_target(128,128).unwrap();
    renderer.render(&mut uploaded,&camera,&target).unwrap();
    let expected=renderer.read_rgba(&target).unwrap();
    let background=scene.background.map(|v|(v.clamp(0.0,1.0)*255.0) as u8);
    assert!(expected.rgba.chunks_exact(4).any(|p|p!=background));
    let payload=uploaded.geometry_bytes;
    measure(n,128,case,wire,opacity,"gpu_upload",payload,0,||renderer.upload(&scene).unwrap(),|out|assert_eq!(out.geometry_bytes,payload));
    measure(n,128,case,wire,opacity,"gpu_submit",payload,image_hash(&expected.rgba),|| {
        renderer.render(&mut uploaded,&camera,&target).unwrap();
    },|()| {
        assert_eq!(renderer.read_rgba(&target).unwrap().rgba,expected.rgba);
    });
    assert_eq!(scene.preparation_stats().geometry_builds,1); assert_eq!(uploaded.geometry_bytes,payload);
}

fn main() {
    for n in [8,24,48] {for case in ["point","cell_uniform","cell_varying","cell_missing"] {prepare(n,case,false);software(n,128,case,false,1.0);}}
    prepare(24,"cell_varying",true);software(24,128,"cell_varying",true,1.0);
    #[cfg(feature="gpu")] {
        let renderer=gpui_scene3d::GpuRenderer::new(wgpu::TextureFormat::Rgba8Unorm).unwrap();
        for n in [8,24,48] {for case in ["point","cell_uniform","cell_varying","cell_missing"] {gpu(&renderer,n,case,false,1.0);}}
        gpu(&renderer,24,"cell_varying",true,1.0);
    }
}

